        /// <summary>
        /// Dòng đã sửa (Modified) tô màu hồng để dễ nhận biết trước khi Lưu.
        /// </summary>
        private void gvData_RowStyle(object sender, DevExpress.XtraGrid.Views.Grid.RowStyleEventArgs e)
        {
            if (e.RowHandle < 0)
                return;

            DataRow drw = gvData.GetDataRow(e.RowHandle);
            if (drw != null && drw.RowState == DataRowState.Modified)
            {
                e.Appearance.BackColor = Color.LightPink;
                e.HighPriority = true;
            }
        }

        #endregion
    }
}

